GRILL_JSON
{
  "cards": [
    {
      "id": "scope-feeds",
      "title": "Which feeds auto-refresh?",
      "body": "The feature says the \"currently loaded feed\" re-fetches every 60 seconds. The glossary defines that as preset or custom. Does the timer apply to both, or only preset feeds?",
      "options": [
        { "key": "a", "text": "Both preset and custom feeds" },
        { "key": "b", "text": "Preset feeds only" }
      ],
      "rec": {
        "option": "a",
        "why": "The glossary's \"currently loaded feed\" covers both kinds, and custom-feed readers want fresh items just as much; splitting the behavior adds a special case."
      }
    },
    {
      "id": "timer-reset",
      "title": "When does the 60-second interval restart?",
      "body": "After which events does the next automatic re-fetch come a full 60 seconds later?",
      "options": [
        { "key": "a", "text": "Reset on every load and refresh, manual or automatic" },
        { "key": "b", "text": "Fixed wall-clock tick every 60s, unaffected by manual refresh" },
        { "key": "c", "text": "Reset only on manual actions, automatic refreshes don't reset it" }
      ],
      "rec": {
        "option": "a",
        "why": "A manual click already delivered fresh data, so counting the next auto-fetch from it avoids a pointless double fetch and keeps the cadence predictable."
      }
    },
    {
      "id": "error-handling",
      "title": "What happens when an automatic re-fetch fails?",
      "body": "If the background re-fetch gets a network error, a non-200, or a 400 from the host guard, what should the app do?",
      "options": [
        { "key": "a", "text": "Show the existing error banner and keep the timer running" },
        { "key": "b", "text": "Show the banner and pause the timer until a manual refresh or new load restarts it" },
        { "key": "c", "text": "Silently keep the old items, no banner, keep the timer running" }
      ],
      "rec": {
        "option": "b",
        "why": "A dead feed would otherwise re-banner every 60 seconds; surfacing the failure once and stopping until the person acts keeps the error visible without spamming."
      }
    },
    {
      "id": "in-flight-overlap",
      "title": "What if a re-fetch is still running at the next tick?",
      "body": "A slow or hung request can still be in flight when 60 seconds have passed. What then?",
      "options": [
        { "key": "a", "text": "Skip the tick; schedule the next attempt 60s after the in-flight one finishes" },
        { "key": "b", "text": "Start a second request anyway; whichever finishes last wins" },
        { "key": "c", "text": "Abort the in-flight request and start a fresh one" }
      ],
      "rec": {
        "option": "a",
        "why": "Skipping avoids out-of-order responses clobbering newer items with older ones and needs no abort plumbing."
      }
    },
    {
      "id": "visibility",
      "title": "Should the timer run while the tab is hidden?",
      "body": "When the browser tab is in the background, should automatic re-fetches continue, pause, or catch up on return?",
      "options": [
        { "key": "a", "text": "Keep fetching every 60s regardless of visibility" },
        { "key": "b", "text": "Pause while hidden; re-fetch immediately when the tab becomes visible again" },
        { "key": "c", "text": "Pause while hidden; resume on the next tick without an immediate fetch" }
      ],
      "rec": {
        "option": "b",
        "why": "Polling a hidden tab wastes requests and can pile up error banners nobody sees, and an immediate fetch on return means the person lands on fresh items."
      }
    },
    {
      "id": "loading-ui",
      "title": "What does the UI show during a background re-fetch?",
      "body": "Manual refresh presumably shows a loading state. Should an automatic re-fetch look the same?",
      "options": [
        { "key": "a", "text": "Same loading state as manual refresh (spinner, list reloads)" },
        { "key": "b", "text": "Silent refresh: keep current items on screen, swap in the new list when it arrives" },
        { "key": "c", "text": "Keep current items plus a subtle updating indicator" }
      ],
      "rec": {
        "option": "b",
        "why": "Blanking or spinning the list every 60 seconds fights the feature's goal of items quietly appearing; a silent swap is also the least new UI."
      }
    },
    {
      "id": "confirm-shared",
      "title": "Confirm shared understanding",
      "body": "To confirm: while a feed is loaded — preset or custom — the app re-fetches exactly that feed every 60 seconds, ignoring any unsubmitted dropdown or custom-URL edits; new items appear without clicking Refresh; the interval, failure, overlap, visibility, and loading behavior are as settled in the cards above.",
      "options": [
        { "key": "a", "text": "Confirmed" },
        { "key": "b", "text": "Not yet — something above needs to change" }
      ],
      "rec": {
        "option": "a",
        "why": "The statement only restates the feature and the settled cards."
      }
    }
  ]
}
